def determinant(a: list[list[float]]) -> float:
    """Determinant by LU elimination with partial pivoting (the input is not modified)."""
    n: int = len(a)
    m: list[list[float]] = []
    for i in range(n):
        row: list[float] = []
        for j in range(n):
            row.append(a[i][j])
        m.append(row)
    det: float = 1.0
    for col in range(n):
        pivot: int = col
        for r in range(col + 1, n):
            if abs(m[r][col]) > abs(m[pivot][col]):
                pivot = r
        if m[pivot][col] == 0.0:
            return 0.0
        if pivot != col:
            for j in range(n):
                tmp: float = m[col][j]
                m[col][j] = m[pivot][j]
                m[pivot][j] = tmp
            det = -det
        det *= m[col][col]
        for r in range(col + 1, n):
            factor: float = m[r][col] / m[col][col]
            for j in range(col, n):
                m[r][j] -= factor * m[col][j]
    return det

